#!/bin/sh
set -eu

# Host keys live in a named volume, so the sandbox keeps its identity across
# rebuilds (and trusting it once in the wizard stays valid).
mkdir -p /etc/ssh/keys
[ -f /etc/ssh/keys/ssh_host_ed25519_key ] || ssh-keygen -q -t ed25519 -N '' -f /etc/ssh/keys/ssh_host_ed25519_key
[ -f /etc/ssh/keys/ssh_host_rsa_key ] || ssh-keygen -q -t rsa -b 3072 -N '' -f /etc/ssh/keys/ssh_host_rsa_key

# deploy.me's sandbox key, generated by `php artisan deployme:sandbox`.
install -d -o deploy -g deploy -m 0700 /home/deploy/.ssh
if [ -f /sandbox-keys/id_ed25519.pub ]; then
  install -o deploy -g deploy -m 0600 /sandbox-keys/id_ed25519.pub /home/deploy/.ssh/authorized_keys
else
  echo "No /sandbox-keys/id_ed25519.pub yet: run \`make sandbox\`." >&2
fi

exec /usr/sbin/sshd -D -e
